defmodule GatewayKit.Context do
  @moduledoc """
  The unit of work that flows through a route's pipeline.

  Stages read and return a `Context`; only `GatewayKit.Endpoint` knows about `Plug.Conn`.

  * `request` — the inbound request, already read in full.
  * `response` — set by the proxy (an upstream answer) or by any stage that short-circuits.
  * `halted?` — `true` when the response was **generated by the gateway** (auth failure, rate
    limit, breaker open, upstream unreachable) rather than returned by an upstream. Stages that
    only make sense for upstream answers — response transforms, status-based retries — use it.
  * `error` — the normalized upstream failure reason (`:timeout`, `:econnrefused`, …), if any.
  * `assigns` — scratch space for stages that need to hand data to their outer half.
  """

  alias GatewayKit.Config.Route
  alias GatewayKit.Context.{Request, Response}

  defmodule Request do
    @moduledoc """
    The inbound request, decoupled from the HTTP server.

    `path` is the full request path as received; `suffix` is the part after the matched route
    prefix, used when `strip_prefix` is on. `headers` are lowercase `{name, value}` pairs.
    """

    defstruct method: "GET",
              path: "/",
              suffix: [],
              query: "",
              headers: [],
              body: "",
              client_ip: "127.0.0.1",
              scheme: "http",
              host: ""

    @type t :: %__MODULE__{
            method: String.t(),
            path: String.t(),
            suffix: [String.t()],
            query: String.t(),
            headers: [{String.t(), String.t()}],
            body: binary(),
            client_ip: String.t(),
            scheme: String.t(),
            host: String.t()
          }
  end

  defmodule Response do
    @moduledoc "The response to send back — an upstream's, or one the gateway generated."

    defstruct status: 502, headers: [], body: ""

    @type t :: %__MODULE__{status: 100..599, headers: [{String.t(), String.t()}], body: binary()}
  end

  defstruct [:route, :request, :started_at, response: nil, halted?: false, error: nil, assigns: %{}]

  @type t :: %__MODULE__{
          route: Route.t(),
          request: Request.t(),
          started_at: DateTime.t(),
          response: Response.t() | nil,
          halted?: boolean(),
          error: term() | nil,
          assigns: map()
        }

  @json_content_type {"content-type", "application/json"}

  @spec new(Request.t(), Route.t()) :: t()
  def new(%Request{} = request, %Route{} = route) do
    %__MODULE__{route: route, request: request, started_at: DateTime.utc_now()}
  end

  @doc "Records an upstream response."
  @spec respond(t(), Response.t()) :: t()
  def respond(%__MODULE__{} = ctx, %Response{} = response), do: %{ctx | response: response}

  @doc "Short-circuits the pipeline with a gateway-generated JSON response."
  @spec halt(t(), 100..599, map(), [{String.t(), String.t()}]) :: t()
  def halt(%__MODULE__{} = ctx, status, body, headers \\ []) when is_map(body) do
    response = %Response{status: status, headers: [@json_content_type | headers], body: Jason.encode!(body)}
    %{ctx | response: response, halted?: true}
  end

  @doc "Records why the upstream call failed, for stages that decide based on the failure kind."
  @spec put_error(t(), term()) :: t()
  def put_error(%__MODULE__{} = ctx, error), do: %{ctx | error: error}

  @spec assign(t(), atom(), term()) :: t()
  def assign(%__MODULE__{assigns: assigns} = ctx, key, value) when is_atom(key) do
    %{ctx | assigns: Map.put(assigns, key, value)}
  end
end
